import json

results = []
for item in items:
    content = item['json']['choices'][0]['message']['content']
    data = json.loads(content)

    if not data.get('valid', True):
        results.append({'json': {
            'valid': False,
            'reason': data.get('reason', 'nierozpoznane słowo'),
        }})
        continue

    results.append({'json': {
        'valid': True,
        'word': data['input_word'],
        'translation': data['translation'],
        'meaning_hint': data.get('meaning_hint', ''),
        'input_lang': data.get('input_lang', 'en'),
        'corrected_from': data.get('corrected_from', ''),
    }})

return results

parameters.jsCode:
const results = [];
for (const item of $input.all()) {
  const data = JSON.parse(item.json.choices[0].message.content);
  const t = $('Parse translation').first().json;
  const word = t.word;
  const translation = t.translation;
  const lang = t.input_lang;
  const ipa = data.ipa || '';
  const phonetic = data.phonetic_pl || '';
  const ex1 = data.example1;
  const ex1t = data.example1_translation;
  const ex2 = data.example2;
  const ex2t = data.example2_translation;
  const ex3 = data.example3;
  const ex3t = data.example3_translation;

  const examples = (a, b, c) => `<div style="text-align:center">• ${a}<br>• ${b}<br>• ${c}</div>`;

  const phoneticBlock = (ipa ? `  <i>${ipa}</i>` : '') + (phonetic ? `  <small>[${phonetic}]</small>` : '');
  let front, back;
  if (lang === 'en') {
    front = `<b>${word}</b>${phoneticBlock}<br><br>${examples(ex1, ex2, ex3)}`;
    back = `<b>${translation}</b><br><br>${examples(ex1t, ex2t, ex3t)}`;
  } else {
    front = `<b>${word}</b><br><br>${examples(ex1, ex2, ex3)}`;
    back = `<b>${translation}</b>${phoneticBlock}<br><br>${examples(ex1t, ex2t, ex3t)}`;
  }

  results.push({ json: { front, back } });
}
return results;
